import { describe, it, expect } from 'vitest';
import {
  MatchSchema,
  MatchStateSchema,
  MockProvider,
  CircuitBreaker,
  QuotaGuard,
  calculateWinProbability,
} from '../src/index.js';

describe('Shared Package Tests', () => {
  it('validates mock match against Zod MatchSchema', async () => {
    const provider = new MockProvider();
    const matches = await provider.getLiveMatches();
    expect(matches.length).toBeGreaterThan(0);

    const parseResult = MatchSchema.safeParse(matches[0]);
    expect(parseResult.success).toBe(true);
  });

  it('MockProvider advances ball-by-ball and produces valid MatchState', async () => {
    const provider = new MockProvider();
    const initialSnapshot = await provider.getMatchSnapshot('match-ind-pak-2024');
    expect(initialSnapshot.currentInnings.runs).toBe(0);

    // Advance 5 balls
    for (let i = 0; i < 5; i++) {
      const { ball, delta } = provider.advanceBall();
      expect(ball).not.toBeNull();
      expect(delta.sequence).toBeGreaterThan(1);
    }

    const updatedSnapshot = await provider.getMatchSnapshot('match-ind-pak-2024');
    expect(updatedSnapshot.currentInnings.runs).toBeGreaterThan(0);

    const validation = MatchStateSchema.safeParse(updatedSnapshot);
    if (!validation.success) {
      console.error(validation.error);
    }
    expect(validation.success).toBe(true);
  });

  it('CircuitBreaker transitions to OPEN after threshold failures', async () => {
    const cb = new CircuitBreaker({ failureThreshold: 2, recoveryTimeMs: 100 });
    const failOp = async () => {
      throw new Error('boom');
    };

    await expect(cb.execute(failOp)).rejects.toThrow('boom');
    await expect(cb.execute(failOp)).rejects.toThrow('boom');

    // Next call should fail immediately with CircuitBreakerError
    await expect(cb.execute(failOp)).rejects.toThrow(/Circuit breaker is OPEN/);
    expect(cb.getState()).toBe('OPEN');
  });

  it('QuotaGuard enforces daily budget limits', () => {
    const guard = new QuotaGuard({ providerName: 'Test', dailyBudget: 2, maxCallsPerMinute: 10 });
    expect(() => guard.checkQuota()).not.toThrow();
    guard.recordCall();

    expect(() => guard.checkQuota()).not.toThrow();
    guard.recordCall();

    // 3rd call exceeds budget of 2
    expect(() => guard.checkQuota()).toThrow(/Daily API quota budget/);
  });

  it('WinProbability calculates deterministic edge cases', () => {
    // 1 off 1 ball remaining
    const resultChasing1off1 = calculateWinProbability({
      format: 'T20',
      inningsNumber: 2,
      teamAId: 'team-ind',
      teamAName: 'India',
      teamBId: 'team-pak',
      teamBName: 'Pakistan',
      battingTeamId: 'team-ind',
      runs: 159,
      wickets: 4,
      balls: 119,
      targetRuns: 160,
    });
    expect(resultChasing1off1.teamAProb).toBeGreaterThanOrEqual(80);

    // All out
    const resultAllOut = calculateWinProbability({
      format: 'T20',
      inningsNumber: 2,
      teamAId: 'team-ind',
      teamAName: 'India',
      teamBId: 'team-pak',
      teamBName: 'Pakistan',
      battingTeamId: 'team-ind',
      runs: 120,
      wickets: 10,
      balls: 80,
      targetRuns: 160,
    });
    expect(resultAllOut.teamAProb).toBe(0);
    expect(resultAllOut.teamBProb).toBe(100);

    // Target achieved
    const resultWon = calculateWinProbability({
      format: 'T20',
      inningsNumber: 2,
      teamAId: 'team-ind',
      teamAName: 'India',
      teamBId: 'team-pak',
      teamBName: 'Pakistan',
      battingTeamId: 'team-ind',
      runs: 160,
      wickets: 6,
      balls: 119,
      targetRuns: 160,
    });
    expect(resultWon.teamAProb).toBe(100);
    expect(resultWon.teamBProb).toBe(0);
  });
});
